WITH t1 AS ( SELECT YEAR, NEW_CONTRACT_AMOUNT FROM BIZ_BUSINESS WHERE ORG_ID = #{companyId} AND YEAR IN
#{item}
AND (YEAR, MONTH) IN ( SELECT YEAR, MAX(MONTH) FROM BIZ_BUSINESS WHERE ORG_ID = #{companyId} GROUP BY YEAR ) ), t2 AS ( SELECT YEAR, REC_AMOUNT_ACC, PROFIT_AMOUNT_ACC FROM BIZ_FINANCE WHERE ORG_ID = #{companyId} AND (YEAR, MONTH) IN ( SELECT YEAR, MAX(MONTH) FROM BIZ_FINANCE WHERE ORG_ID = #{companyId} GROUP BY YEAR ) ), t3 AS ( SELECT YEAR, SUM(PRODUCT_AMOUNT) AS PRODUCT_AMOUNT_TOTAL FROM BIZ_PRODUCT GROUP BY YEAR ) SELECT t1.YEAR AS assYear, t1.NEW_CONTRACT_AMOUNT AS newContractTotalComp, t2.REC_AMOUNT_ACC AS incomeTotalComp, t2.PROFIT_AMOUNT_ACC AS profitTotalComp, t3.PRODUCT_AMOUNT_TOTAL AS proValueTotalComp, t4.ID AS id, t5.STATUS AS goalModifyStatus FROM t1 JOIN t2 ON t1.YEAR = t2.YEAR JOIN t3 ON t1.YEAR = t3.YEAR JOIN BIZ_COMPANY_GOAL t4 ON t1.YEAR = t4.ASS_YEAR LEFT JOIN BIZ_COMPANY_GOAL_MODIFY t5 ON t4.ID = t5.GOAL_ID AND t5.CREATE_TIME = (SELECT MAX(CREATE_TIME) FROM BIZ_COMPANY_GOAL_MODIFY WHERE t4.ID = BIZ_COMPANY_GOAL_MODIFY.GOAL_ID) ORDER BY t1.YEAR DESC
